use vstd::prelude::*;

verus! {
    /// A simple alias for a 2-D matrix.
    type Matrix<T> = Vec<Vec<T>>;

    /// Broadcast a 1-D vector `a` into an R×C matrix according to `shape = [R, C]`.
    ///
    /// Preconditions:
    ///   - shape.len() == 2
    ///   - shape[0] > 0  (R > 0)
    ///   - shape[1] > 0  (C > 0)
    ///   - a.len() > 0
    ///   - a.len() == R or a.len() == C
    ///
    /// Postconditions:
    ///   - The result has exactly R rows.
    ///   - For all 0 ≤ i < R, 0 ≤ j < C:
    ///       • if a.len() == R,  ret[i][j] == a[i]   (column broadcast)
    ///       • otherwise        ret[i][j] == a[j]   (row broadcast)
    fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
        requires
            shape.len() == 2,
            shape[0] > 0,
            shape[1] > 0,
            a.len() > 0,
            a.len() == shape[0] as usize || a.len() == shape[1] as usize,
        ensures
            ret.len() == shape[0] as usize,
            forall|i: usize, j: usize|
                (i < shape[0] as usize && j < shape[1] as usize) ==>
                if a.len() == shape[0] as usize {
                    ret[i][j] == a[i]
                } else {
                    ret[i][j] == a[j]
                },
    {
        let R = shape[0] as usize;
        let C = shape[1] as usize;

        // Build the matrix row by row.
        let mut ret: Matrix<i8> = Vec::new();
        let mut i: usize = 0;
        while i < R
            invariant
                i <= R,
                ret.len() == i,
            decreases R - i,
        {
            // Build a single row of length C.
            let mut row: Vec<i8> = Vec::new();
            let mut j: usize = 0;
            while j < C
                invariant
                    j <= C,
                    row.len() == j,
                decreases C - j,
            {
                // Decide whether we're broadcasting a column or a row.
                let val: i8 =
                    if a.len() == R {
                        // column-broadcast: each row i repeats a[i]
                        a[i]
                    } else {
                        // row-broadcast: each column j repeats a[j]
                        a[j]
                    };
                row.push(val);
                j += 1;
            }
            // Now row.len() == C
            assert(row.len() == C);
            ret.push(row);
            i += 1;
        }
        // Now ret.len() == R
        assert(ret.len() == R);
        ret
    }
}

fn main() {
    // example usage (not verified):
    let v = Vec::from_slice(&[1i8, 2, 3]);
    let shape = Vec::from_slice(&[3u8, 5]);
    let m = broadcast(v.clone(), shape.clone());
    // m is 3×5, column-broadcast of [1,2,3].
}